def solve(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    # ----------------------------------------------------------------------
    # 1. Collect positions of each non‑zero value
    # ----------------------------------------------------------------------
    pos = {}
    for i in range(rows):
        for j in range(cols):
            v = grid[i][j]
            if v != 0:
                pos.setdefault(v, []).append((i, j))

    # ----------------------------------------------------------------------
    # 2. Keep only numbers that appear exactly twice and are aligned
    # ----------------------------------------------------------------------
    lines = {}                               # value -> info dict
    for v, lst in pos.items():
        if len(lst) != 2:
            continue                         # ignore (not a pair)
        (r0, c0), (r1, c1) = lst
        if r0 == r1:                         # horizontal
            lines[v] = {'anchors': [(r0, c0), (r1, c1)],
                        'orientation': 'horizontal',
                        'shifted': False}
        elif c0 == c1:                       # vertical
            lines[v] = {'anchors': [(r0, c0), (r1, c1)],
                        'orientation': 'vertical',
                        'shifted': False}
        # otherwise ignore (diagonal) – not present in the task

    # ----------------------------------------------------------------------
    # 3. Resolve row / column conflicts (anchor rows/columns shared by
    #    different numbers).  The smallest number is shifted down/right.
    # ----------------------------------------------------------------------
    while True:
        # ----- row conflicts -----
        row_of_numbers = {}
        for num, info in lines.items():
            for r, _ in info['anchors']:
                row_of_numbers.setdefault(r, set()).add(num)

        conflict = False
        for r, num_set in row_of_numbers.items():
            if len(num_set) > 1:
                smallest = min(num_set)
                info = lines[smallest]
                # move the whole line one row down
                new_anchors = [(r + 1, c) for (r, c) in info['anchors']]
                if all(0 <= nr < rows for nr, _ in new_anchors):
                    info['anchors'] = new_anchors
                    info['shifted'] = True
                    conflict = True
                break
        if conflict:
            continue

        # ----- column conflicts -----
        col_of_numbers = {}
        for num, info in lines.items():
            for _, c in info['anchors']:
                col_of_numbers.setdefault(c, set()).add(num)

        for c, num_set in col_of_numbers.items():
            if len(num_set) > 1:
                smallest = min(num_set)
                info = lines[smallest]
                # move the whole line one column to the right
                new_anchors = [(r, c + 1) for (r, c) in info['anchors']]
                if all(0 <= nc < cols for _, nc in new_anchors):
                    info['anchors'] = new_anchors
                    info['shifted'] = True
                    conflict = True
                break
        if not conflict:
            break

