            r = r1
            c_left, c_right = sorted((c1, c2))
            for c in range(c_left, c_right + 1):
                out[r][c] = num

    # verticals afterwards
    for num, info in lines.items():
        if info['orientation'] == 'vertical':
            (r1, c1), (r2, c2) = info['anchors']
            c = c1
            r_top, r_bottom = sorted((r1, r2))
            for r in range(r_top, r_bottom + 1):
                out[r][c] = num

