                v_col = vinfo['anchors'][0][1]
                v_top, v_bottom = sorted((vinfo['anchors'][0][0],
                                          vinfo['anchors'][1][0]))
                if v_top <= h_row <= v_bottom and h_left <= v_col <= h_right:
                    to_shift.append(num)
                    break

        if to_shift:
            # apply the down‑shift
            for num in to_shift:
                info = lines[num]
                new_anchors = [(r + 1, c) for (r, c) in info['anchors']]
                if all(0 <= nr < rows for nr, _ in new_anchors):
                    info['anchors'] = new_anchors

